//! Frozen bytes generated by production serialization at 88e8615c0, from the
//! existing linux-v4.execution.json request. Never regenerate from the new types.
use super::*;
use crate::control::{ControlMsg, ControlReply};

#[test]
fn w_owned_none_matches_released_wire_and_specification_bytes() {
    let config = bincode::config::standard();
    let bytes = include_bytes!("fixtures/explicit-v10.prepare.bin");
    let (message, used): (ControlMsg, _) =
        bincode::serde::decode_from_slice(bytes, config).unwrap();
    assert_eq!(used, bytes.len());
    let ControlMsg::Execution(request) = message else {
        panic!()
    };
    let ExecutionRequest::Prepare(request) = *request else {
        panic!()
    };
    assert_eq!(
        serde_json::to_vec(&request.specification).unwrap(),
        include_bytes!("fixtures/explicit-v10.specification.json")
    );
    assert_eq!(
        bincode::serde::encode_to_vec(
            ControlMsg::Execution(Box::new(ExecutionRequest::Prepare(request))),
            config
        )
        .unwrap(),
        bytes
    );
}

#[tokio::test]
async fn w_owned_new_kernel_accepts_released_v10_handshake() {
    let root = tempfile::tempdir().unwrap();
    let path = root.path().join("old-peer.sock");
    let listener = tokio::net::UnixListener::bind(&path).unwrap();
    let (message, _): (ControlMsg, _) = bincode::serde::decode_from_slice(
        include_bytes!("fixtures/explicit-v10.handshake.bin"),
        bincode::config::standard(),
    )
    .unwrap();
    let ControlMsg::Execution(request) = message else {
        panic!()
    };
    let ExecutionRequest::Handshake(old) = *request else {
        panic!()
    };
    let expected_secret = old.client_secret.clone();
    let peer = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let hello: ControlMsg = crate::read_frame(&mut stream).await.unwrap();
        let ControlMsg::Execution(hello) = hello else {
            panic!()
        };
        let ExecutionRequest::Handshake(hello) = *hello else {
            panic!()
        };
        assert_eq!(hello.required_contract, old.required_contract);
        crate::write_frame(
            &mut stream,
            &ControlReply::Execution(Box::new(ExecutionReply::Handshake {
                envelope_version: old.required_contract,
                executor_boot: ExecutorBootId::fresh().unwrap(),
                mode: old.mode,
            })),
        )
        .await
        .unwrap();
    });
    RegisteredExecutorConnection::connect(&path, expected_secret)
        .await
        .unwrap();
    peer.await.unwrap();
}

#[test]
fn w_owned_specification_roundtrip_preserves_immutable_input() {
    let explicit: ExecutionSpecification =
        serde_json::from_slice(include_bytes!("fixtures/explicit-v10.specification.json")).unwrap();
    for policy in [
        AmbientEnvironment::None,
        AmbientEnvironment::SupervisorAllowed {
            proxy_policy: AmbientProxyPolicy::RejectSecret,
        },
        AmbientEnvironment::SupervisorAllowed {
            proxy_policy: AmbientProxyPolicy::Exclude,
        },
    ] {
        let mut input = explicit.clone();
        input.ambient_environment = policy;
        let encoded = serde_json::to_vec(&input).unwrap();
        assert_eq!(
            serde_json::from_slice::<ExecutionSpecification>(&encoded).unwrap(),
            input
        );
        if input.ambient_environment == AmbientEnvironment::None {
            let config = bincode::config::standard();
            let encoded = bincode::serde::encode_to_vec(&input, config).unwrap();
            let (decoded, used): (ExecutionSpecification, _) =
                bincode::serde::decode_from_slice(&encoded, config).unwrap();
            assert_eq!(used, encoded.len());
            assert_eq!(decoded, input);
        } else {
            let mut value = serde_json::to_value(&input).unwrap();
            value["version"] = serde_json::json!(EXECUTION_SPECIFICATION_VERSION + 1);
            assert!(serde_json::from_value::<ExecutionSpecification>(value).is_err());
        }
    }
}
